import type { Quat, Vec3 } from '../contracts/math';
import type { ZoneDescriptor } from '../contracts/zones';
import type { ConveyorConfig, FanConfig, TeleporterConfig } from '../obstacles/types';
import type { BoxZone } from '../obstacles/zones';
import { validateHole } from './Hole';
import type { Hole, ObstacleDescriptor, SurfaceDescriptor, SurfaceMaterial } from './types';

/** Runtime force obstacles produced next to the plain hole descriptor. */
export type ForceObstacleConfig = TeleporterConfig | FanConfig | ConveyorConfig;

/** A hole descriptor plus the runtime-only data that does not fit into it. */
export interface HoleBlueprint {
  hole: Hole;
  zones: ZoneDescriptor[];
  forceObstacles: ForceObstacleConfig[];
}

export interface CupOptions {
  position: Vec3;
  radius?: number;
  captureDepth?: number;
}

export interface HoleBuilderOptions {
  id: string;
  name: string;
  par: number;
  spawn?: Vec3;
  cup?: CupOptions;
  bounds?: { min: Vec3; max: Vec3 };
  /** Horizontal padding used when bounds are derived from the placed geometry. */
  padding?: number;
}

export interface SurfaceOptions {
  id?: string;
  position: Vec3;
  size: Vec3;
  material?: SurfaceMaterial;
  /** Yaw in radians, ignored when an explicit rotation is supplied. */
  yaw?: number;
  rotation?: Quat;
  friction?: number;
  restitution?: number;
}

export interface CurveOptions {
  id?: string;
  /** Center of the arc the segments are laid out around. */
  center: Vec3;
  radius: number;
  width: number;
  startAngle: number;
  sweepAngle: number;
  segments?: number;
  thickness?: number;
  material?: SurfaceMaterial;
  friction?: number;
}

export interface WallOptions {
  id?: string;
  position: Vec3;
  size: Vec3;
  restitution?: number;
}

export interface BumperOptions {
  id?: string;
  position: Vec3;
  size?: Vec3;
  restitution?: number;
}

export interface SpinnerOptions {
  id?: string;
  position: Vec3;
  size?: Vec3;
  axis?: Vec3;
  speed?: number;
  phase?: number;
}

export interface MovingPlatformOptions {
  id?: string;
  position: Vec3;
  size?: Vec3;
  axis?: Vec3;
  speed?: number;
  distance?: number;
  phase?: number;
}

/** Axis aligned box volume; yaw only applies to the runtime force volumes. */
export interface VolumeOptions {
  id?: string;
  position: Vec3;
  size: Vec3;
  yaw?: number;
}

export interface TeleporterOptions extends VolumeOptions {
  exitPosition: Vec3;
  exitVelocityScale?: number;
  clearAngularVelocity?: boolean;
}

export interface FanOptions extends VolumeOptions {
  direction: Vec3;
  maxForce: number;
  falloff?: boolean;
  pulse?: { period: number; minMultiplier: number };
}

export interface ConveyorOptions extends VolumeOptions {
  direction: Vec3;
  targetSpeed: number;
  coupling?: number;
}

export interface HazardVolumeOptions extends VolumeOptions {
  penaltyStrokes?: number;
  resetPosition?: Vec3;
}

type WithOptionalId<T> = T extends { id: string } ? Omit<T, 'id'> & { id?: string } : never;

/** Any obstacle descriptor; the builder fills in a generated id when omitted. */
export type ObstacleInput = WithOptionalId<ObstacleDescriptor>;

const DEFAULT_CUP_RADIUS = 0.32;
const DEFAULT_CUP_DEPTH = 0.3;
const DEFAULT_CURVE_SEGMENTS = 6;
const DEFAULT_THICKNESS = 0.4;
/** Segments overlap slightly so an approximated curve has no visible seams. */
const CURVE_OVERLAP = 1.04;

const clone = (value: Vec3): Vec3 => ({ x: value.x, y: value.y, z: value.z });
const half = (size: Vec3): Vec3 => ({
  x: Math.abs(size.x) / 2,
  y: Math.abs(size.y) / 2,
  z: Math.abs(size.z) / 2,
});
const yawQuat = (yaw: number): Quat => ({ x: 0, y: Math.sin(yaw / 2), z: 0, w: Math.cos(yaw / 2) });

function toCup(cup: CupOptions): Hole['cup'] {
  return {
    position: clone(cup.position),
    radius: cup.radius ?? DEFAULT_CUP_RADIUS,
    captureDepth: cup.captureDepth ?? DEFAULT_CUP_DEPTH,
  };
}

function boxZone(position: Vec3, size: Vec3, yaw?: number): BoxZone {
  const zone: BoxZone = { shape: 'box', center: clone(position), halfExtents: half(size) };
  if (yaw !== undefined && yaw !== 0) zone.rotationY = yaw;
  return zone;
}

function aabb(position: Vec3, size: Vec3): { min: Vec3; max: Vec3 } {
  const extents = half(size);
  return {
    min: { x: position.x - extents.x, y: position.y - extents.y, z: position.z - extents.z },
    max: { x: position.x + extents.x, y: position.y + extents.y, z: position.z + extents.z },
  };
}

/**
 * Fluent level builder for a single hole. Every method maps onto the plain
 * descriptors consumed by the renderer, physics and obstacle runtime, so course
 * data stays serializable while authoring stays readable.
 */
export class HoleBuilder {
  private readonly surfaces: SurfaceDescriptor[] = [];
  private readonly obstacles: ObstacleDescriptor[] = [];
  private readonly zones: ZoneDescriptor[] = [];
  private readonly forceObstacles: ForceObstacleConfig[] = [];
  private readonly usedIds = new Set<string>();
  private counter = 0;
  private par: number;
  private spawn: Vec3 | null;
  private cup: Hole['cup'] | null;
  private bounds: Hole['bounds'] | null;

  constructor(private readonly options: HoleBuilderOptions) {
    this.par = options.par;
    this.spawn = options.spawn ? clone(options.spawn) : null;
    this.cup = options.cup ? toCup(options.cup) : null;
    this.bounds = options.bounds
      ? { min: clone(options.bounds.min), max: clone(options.bounds.max) }
      : null;
  }

  setSpawn(position: Vec3): this {
    this.spawn = clone(position);
    return this;
  }

  setPar(par: number): this {
    this.par = par;
    return this;
  }

  setBounds(min: Vec3, max: Vec3): this {
    this.bounds = { min: clone(min), max: clone(max) };
    return this;
  }

  /** Places the cup of this hole. */
  addHole(cup: CupOptions): this {
    this.cup = toCup(cup);
    return this;
  }

  addFloor(options: SurfaceOptions): this {
    return this.pushSurface('box', 'floor', options);
  }

  addRamp(options: SurfaceOptions): this {
    return this.pushSurface('ramp', 'ramp', options);
  }

  /** Approximates a banked curve with box segments laid along an arc. */
  addCurve(options: CurveOptions): this {
    if (!(options.radius > 0)) throw new Error(this.message('curve radius must be positive'));
    if (!(options.width > 0)) throw new Error(this.message('curve width must be positive'));
    if (!options.sweepAngle) throw new Error(this.message('curve sweepAngle must not be zero'));

    const segments = Math.max(1, Math.round(options.segments ?? DEFAULT_CURVE_SEGMENTS));
    const baseId = options.id ?? this.nextId('curve');
    const step = options.sweepAngle / segments;
    const thickness = options.thickness ?? DEFAULT_THICKNESS;
    const length = Math.abs(options.radius * step) * CURVE_OVERLAP;

    for (let index = 0; index < segments; index += 1) {
      const angle = options.startAngle + step * (index + 0.5);
      this.addFloor({
        id: `${baseId}-${index + 1}`,
        position: {
          x: options.center.x + Math.cos(angle) * options.radius,
          y: options.center.y,
          z: options.center.z + Math.sin(angle) * options.radius,
        },
        size: { x: options.width, y: thickness, z: length },
        material: options.material ?? 'green',
        yaw: -angle,
        ...(options.friction !== undefined ? { friction: options.friction } : {}),
      });
    }
    return this;
  }

  addWall(options: WallOptions): this {
    return this.pushObstacle('wall', {
      id: options.id,
      type: 'wall',
      transform: { position: clone(options.position) },
      size: clone(options.size),
      ...(options.restitution !== undefined ? { restitution: options.restitution } : {}),
    });
  }

  addBumper(options: BumperOptions): this {
    return this.pushObstacle('bumper', {
      id: options.id,
      type: 'bumper',
      transform: { position: clone(options.position) },
      size: options.size ? clone(options.size) : { x: 1, y: 1, z: 1 },
      restitution: options.restitution ?? 1.2,
    });
  }

  addSpinner(options: SpinnerOptions): this {
    return this.pushObstacle('spinner', {
      id: options.id,
      type: 'spinner',
      transform: { position: clone(options.position) },
      size: options.size ? clone(options.size) : { x: 5, y: 0.4, z: 0.5 },
      motion: {
        kind: 'rotate',
        axis: options.axis ? clone(options.axis) : { x: 0, y: 1, z: 0 },
        speed: options.speed ?? 1.5,
        ...(options.phase !== undefined ? { phase: options.phase } : {}),
      },
    });
  }

  addMovingPlatform(options: MovingPlatformOptions): this {
    return this.pushObstacle('platform', {
      id: options.id,
      type: 'platform',
      transform: { position: clone(options.position) },
      size: options.size ? clone(options.size) : { x: 2.5, y: 0.35, z: 2.5 },
      motion: {
        kind: 'translate',
        axis: options.axis ? clone(options.axis) : { x: 1, y: 0, z: 0 },
        speed: options.speed ?? 1,
        distance: options.distance ?? 2,
        ...(options.phase !== undefined ? { phase: options.phase } : {}),
      },
    });
  }

  /** Escape hatch for descriptors without a dedicated helper (gates, pillars). */
  addObstacle(obstacle: ObstacleInput): this {
    return this.pushObstacle(obstacle.type, obstacle);
  }

  addWater(options: HazardVolumeOptions): this {
    const id = this.useId('water', options.id);
    const penaltyStrokes = options.penaltyStrokes ?? 1;
    this.obstacles.push({
      id,
      type: 'water',
      transform: { position: clone(options.position) },
      size: clone(options.size),
      penaltyStrokes,
    });
    this.zones.push(this.hazardZone(id, 'water', options, penaltyStrokes));
    return this;
  }

  addKillZone(options: HazardVolumeOptions): this {
    const id = this.useId('kill-zone', options.id);
    const penaltyStrokes = options.penaltyStrokes ?? 1;
    this.obstacles.push({
      id,
      type: 'void',
      transform: { position: clone(options.position) },
      size: clone(options.size),
      penaltyStrokes,
    });
    this.zones.push(this.hazardZone(id, 'kill', options, penaltyStrokes));
    return this;
  }

  addTeleporter(options: TeleporterOptions): this {
    const config: TeleporterConfig = {
      id: this.useId('teleporter', options.id),
      kind: 'teleporter',
      entryZone: boxZone(options.position, options.size, options.yaw),
      exitPosition: clone(options.exitPosition),
    };
    if (options.exitVelocityScale !== undefined) config.exitVelocityScale = options.exitVelocityScale;
    if (options.clearAngularVelocity !== undefined) {
      config.clearAngularVelocity = options.clearAngularVelocity;
    }
    this.forceObstacles.push(config);
    return this;
  }

  addFan(options: FanOptions): this {
    const config: FanConfig = {
      id: this.useId('fan', options.id),
      kind: 'fan',
      zone: boxZone(options.position, options.size, options.yaw),
      direction: clone(options.direction),
      maxForce: options.maxForce,
    };
    if (options.falloff !== undefined) config.falloff = options.falloff;
    if (options.pulse) config.pulse = { ...options.pulse };
    this.forceObstacles.push(config);
    return this;
  }

  addConveyor(options: ConveyorOptions): this {
    const config: ConveyorConfig = {
      id: this.useId('conveyor', options.id),
      kind: 'conveyor',
      zone: boxZone(options.position, options.size, options.yaw),
      direction: clone(options.direction),
      targetSpeed: options.targetSpeed,
    };
    if (options.coupling !== undefined) config.coupling = options.coupling;
    this.forceObstacles.push(config);
    return this;
  }

  /** Plain descriptor accepted by course data and every runtime system. */
  buildHole(): Hole {
    if (!this.spawn) throw new Error(this.message('spawn position is required'));
    if (!this.cup) throw new Error(this.message('addHole() must place the cup'));

    const hole: Hole = {
      id: this.options.id,
      name: this.options.name,
      par: this.par,
      spawn: clone(this.spawn),
      cup: toCup(this.cup),
      bounds: this.bounds
        ? { min: clone(this.bounds.min), max: clone(this.bounds.max) }
        : this.deriveBounds(),
      surfaces: this.surfaces.map((surface) => ({ ...surface })),
      obstacles: this.obstacles.map((obstacle) => ({ ...obstacle })),
    };
    validateHole(hole);
    return hole;
  }

  /** Hole descriptor together with the runtime zones and force obstacles. */
  build(): HoleBlueprint {
    return {
      hole: this.buildHole(),
      zones: this.zones.map((zone) => ({ ...zone })),
      forceObstacles: this.forceObstacles.map((config) => ({ ...config })),
    };
  }

  private hazardZone(
    id: string,
    type: 'water' | 'kill',
    options: HazardVolumeOptions,
    penaltyStrokes: number,
  ): ZoneDescriptor {
    const zone: ZoneDescriptor = { id, type, bounds: aabb(options.position, options.size), penaltyStrokes };
    if (options.resetPosition) zone.resetPosition = clone(options.resetPosition);
    return zone;
  }

  private deriveBounds(): Hole['bounds'] {
    const pad = this.options.padding ?? 2;
    const min = { x: Infinity, y: Infinity, z: Infinity };
    const max = { x: -Infinity, y: -Infinity, z: -Infinity };
    const include = (position: Vec3, size?: Vec3): void => {
      const extents = size ? half(size) : { x: 0, y: 0, z: 0 };
      min.x = Math.min(min.x, position.x - extents.x);
      min.y = Math.min(min.y, position.y - extents.y);
      min.z = Math.min(min.z, position.z - extents.z);
      max.x = Math.max(max.x, position.x + extents.x);
      max.y = Math.max(max.y, position.y + extents.y);
      max.z = Math.max(max.z, position.z + extents.z);
    };

    for (const surface of this.surfaces) include(surface.transform.position, surface.size);
    for (const obstacle of this.obstacles) include(obstacle.transform.position, obstacle.size);
    for (const zone of this.zones) {
      include(zone.bounds.min);
      include(zone.bounds.max);
    }
    if (this.spawn) include(this.spawn);
    if (this.cup) include(this.cup.position);

    if (!Number.isFinite(min.x)) {
      return { min: { x: -pad, y: -pad, z: -pad }, max: { x: pad, y: pad, z: pad } };
    }
    return {
      min: { x: min.x - pad, y: min.y - pad * 2, z: min.z - pad },
      max: { x: max.x + pad, y: max.y + pad * 3, z: max.z + pad },
    };
  }

  private pushSurface(shape: SurfaceDescriptor['shape'], prefix: string, options: SurfaceOptions): this {
    const rotation = options.rotation ?? (options.yaw !== undefined ? yawQuat(options.yaw) : undefined);
    const surface: SurfaceDescriptor = {
      id: this.useId(prefix, options.id),
      transform: { position: clone(options.position) },
      shape,
      size: clone(options.size),
      material: options.material ?? 'green',
    };
    if (rotation) surface.transform.rotation = rotation;
    if (options.friction !== undefined) surface.friction = options.friction;
    if (options.restitution !== undefined) surface.restitution = options.restitution;
    this.surfaces.push(surface);
    return this;
  }

  private pushObstacle(prefix: string, input: ObstacleInput): this {
    const id = this.useId(prefix, input.id);
    this.obstacles.push({ ...input, id } as unknown as ObstacleDescriptor);
    return this;
  }

  private nextId(prefix: string): string {
    this.counter += 1;
    return `${prefix}-${this.counter}`;
  }

  private useId(prefix: string, id?: string): string {
    const value = id ?? this.nextId(prefix);
    if (this.usedIds.has(value)) throw new Error(this.message(`duplicate element id "${value}"`));
    this.usedIds.add(value);
    return value;
  }

  private message(text: string): string {
    return `Hole ${this.options.id}: ${text}`;
  }
}

export function createHoleBuilder(options: HoleBuilderOptions): HoleBuilder {
  return new HoleBuilder(options);
}
