  h: HoleBuilder,
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  material: SurfaceMaterial = 'green',
  y = 0,
) => h.addFloor({ id, position: v(x, y, z), size: v(sx, 0.4, sz), material });

const w = (h: HoleBuilder, id: string, x: number, z: number, sx: number, sz: number) =>
  h.addWall({ id, position: v(x, 0.7, z), size: v(sx, 1.4, sz), restitution: 0.35 });

const water = (h: HoleBuilder, id: string, x: number, z: number, sx: number, sz: number) =>
  h.addWater({ id, position: v(x, 0.1, z), size: v(sx, 0.4, sz), penaltyStrokes: 1 });

interface HoleSetup {
  id: string;
  name: string;
  par: number;
  spawn: { x: number; y: number; z: number };
  width: number;
  length: number;
  cup: { x: number; z: number; y?: number };
}

const hole = (setup: HoleSetup, configure: (h: HoleBuilder) => void): Hole => {
  const builder = createHoleBuilder({
    id: setup.id,
    name: setup.name,
    par: setup.par,
    spawn: setup.spawn,
    bounds: b(setup.width, setup.length),
  });
  builder.addHole({ position: v(setup.cup.x, setup.cup.y ?? 0.35, setup.cup.z), radius: 0.32, captureDepth: 0.35 });
  configure(builder);
  return builder.buildHole();
};

